import{_ as a,o as i,c as t,ag as o}from"./chunks/framework.CvZZEx4j.js";const g=JSON.parse('{"title":"配置你的角色卡","description":"","frontmatter":{},"headers":[],"relativePath":"card-author/setup.md","filePath":"card-author/setup.md","lastUpdated":null}'),e={name:"card-author/setup.md"};function r(s,l,n,h,d,c){return i(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="配置你的角色卡" tabindex="-1">配置你的角色卡 <a class="header-anchor" href="#配置你的角色卡" aria-label="Permalink to &quot;配置你的角色卡&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前提</p><p>确保你已经安装了 Galgame 界面插件，并且当前打开了你要配置的角色卡聊天界面。</p></div><h2 id="第一步-上传资源" tabindex="-1">第一步：上传资源 <a class="header-anchor" href="#第一步-上传资源" aria-label="Permalink to &quot;第一步：上传资源&quot;">​</a></h2><h3 id="上传角色立绘" tabindex="-1">上传角色立绘 <a class="header-anchor" href="#上传角色立绘" aria-label="Permalink to &quot;上传角色立绘&quot;">​</a></h3><ol><li>点击 Galgame 按钮打开覆盖层</li><li>打开 <strong>设置面板</strong> → 进入 <strong>资源管理器</strong></li><li>选择 <strong>立绘</strong> 分类</li><li>点击 <strong>上传</strong>，选择角色立绘图片</li></ol><div class="tip custom-block"><p class="custom-block-title">批量上传</p><p>如果你有多张表情差分图，使用 <strong>批量上传</strong> 功能一次完成。插件会自动分配表情类型。</p></div><p><strong>立绘推荐规格</strong>：</p><ul><li>格式：PNG（透明背景）</li><li>分辨率：宽度 512px 以上</li></ul><h3 id="上传背景图" tabindex="-1">上传背景图 <a class="header-anchor" href="#上传背景图" aria-label="Permalink to &quot;上传背景图&quot;">​</a></h3><ol><li>在资源管理器中选择 <strong>背景</strong> 分类</li><li>点击 <strong>上传</strong>，为每张图命名场景名称（如「教室」「公园」「夜晚街道」）</li></ol><h3 id="添加-live2d-模型-可选" tabindex="-1">添加 Live2D 模型（可选） <a class="header-anchor" href="#添加-live2d-模型-可选" aria-label="Permalink to &quot;添加 Live2D 模型（可选）&quot;">​</a></h3><ol><li>打开 <strong>设置面板</strong> → <strong>Live2D 设置</strong></li><li>选择角色名 → 添加 Live2D 模型（本地上传或填写远程 URL）</li><li>使用 <strong>位置编辑器</strong> 拖拽调整模型的位置和大小</li><li>选择模型的显示槽位（左/右）</li></ol><h2 id="第二步-绑定设置" tabindex="-1">第二步：绑定设置 <a class="header-anchor" href="#第二步-绑定设置" aria-label="Permalink to &quot;第二步：绑定设置&quot;">​</a></h2><h3 id="tts-音色绑定" tabindex="-1">TTS 音色绑定 <a class="header-anchor" href="#tts-音色绑定" aria-label="Permalink to &quot;TTS 音色绑定&quot;">​</a></h3><ol><li>打开 <strong>设置面板</strong> → <strong>音频设置</strong></li><li>在「角色音色」区域，为每个角色选择合适的音色</li><li>保存</li></ol><h3 id="bgm-白名单-可选" tabindex="-1">BGM 白名单（可选） <a class="header-anchor" href="#bgm-白名单-可选" aria-label="Permalink to &quot;BGM 白名单（可选）&quot;">​</a></h3><ol><li>在设置面板中找到「BGM 白名单」</li><li>添加你推荐的背景音乐名称</li><li>AI 将只从白名单中选择 BGM</li></ol><h3 id="选择皮肤-可选" tabindex="-1">选择皮肤（可选） <a class="header-anchor" href="#选择皮肤-可选" aria-label="Permalink to &quot;选择皮肤（可选）&quot;">​</a></h3><ol><li>在「显示设置」中选择合适的界面皮肤</li><li>选择与你角色卡风格搭配的主题</li></ol><h2 id="第三步-注入世界书" tabindex="-1">第三步：注入世界书 <a class="header-anchor" href="#第三步-注入世界书" aria-label="Permalink to &quot;第三步：注入世界书&quot;">​</a></h2><ol><li>在设置面板中点击 <strong>「注入世界书」</strong> 按钮</li><li>插件会自动生成 COT 格式规范，内容包含： <ul><li>你上传的所有表情名称</li><li>你上传的所有场景名称</li><li>TTS 音色列表和角色绑定</li><li>BGM 白名单</li></ul></li><li>世界书会全局启用</li></ol><div class="warning custom-block"><p class="custom-block-title">重要</p><p>每次修改资源后（增删立绘/背景/音色），都建议重新点击「注入世界书」以更新格式规范。</p></div><h2 id="第四步-测试" tabindex="-1">第四步：测试 <a class="header-anchor" href="#第四步-测试" aria-label="Permalink to &quot;第四步：测试&quot;">​</a></h2><ol><li>发送一条消息给 AI</li><li>检查以下内容是否正常： <ul><li>✅ Galgame 覆盖层正常显示</li><li>✅ AI 按格式输出对话和旁白</li><li>✅ 立绘正确显示并随表情切换</li><li>✅ 背景正确加载</li><li>✅ TTS 语音正常播放（如已启用）</li><li>✅ Live2D 正常展示（如已添加）</li></ul></li></ol><p>一切正常？进入 <a href="/galgame/card-author/export.html">第二步：导出角色卡</a>。</p>',25)])])}const p=a(e,[["render",r]]);export{g as __pageData,p as default};
